      Some(b) if b >= b'0' && b <= b'9' => {
        s.write_byte(b)
        self.pos += 1
      }
      Some(b'_') => {
        // Skip underscore digit separators
        self.pos += 1
      }
      _ => break
    }
  }
  let text = s.to_string()
  if text.is_empty() {
    raise InvalidSyntax("expected integer at line \(self.line)")
  }
  let n : Int = @string.from_str(text) catch {
    _ => raise InvalidValue("invalid integer '\(text)' at line \(self.line)")
  }
  n
