// Parser state.
struct TomlParser {
  text : String
  pos : Int   // current byte/unit position
  line : Int  // current line number (1-based)
}

fn TomlParser::new(text : String) -> TomlParser {
  { text, pos: 0, line: 1 }
}

// Peek at the current character code as Int (for ASCII comparison).
fn peek(self : TomlParser) -> Int? {
  if self.pos >= self.text.length() {
    None
  } else {
    Some(self.text[self.pos].to_int())
  }
}

// Advance past the current character and return its code.
fn advance(self : TomlParser) -> Int raise TomlError {
  if self.pos >= self.text.length() {
    raise InvalidSyntax("unexpected end of input")
  }
  let code = self.text[self.pos].to_int()
  self.pos += 1
  if code == 0x0A {
    self.line += 1
  }
  code
}

// Skip whitespace (spaces and tabs), but not newlines.
fn skip_ws(self : TomlParser) -> Unit {
  loop {
    match self.peek() {
      Some(c) if c == 0x20 || c == 0x09 => { self.pos += 1 }
      _ => break
    }
  }
}

// Skip whitespace including newlines and carriage returns.
fn skip_ws_nl(self : TomlParser) -> Unit {
  loop {
    match self.peek() {
      Some(c) if c == 0x20 || c == 0x09 || c == 0x0A || c == 0x0D => {
        if c == 0x0A { self.line += 1 }
        self.pos += 1
      }
      _ => break
    }
  }
}

// Skip a comment starting at the current position (after a #).
fn skip_comment(self : TomlParser) -> Unit {
  loop {
    match self.peek() {
      Some(c) if c == 0x0A || c == 0x0D => {
        if c == 0x0A { self.line += 1 }
        self.pos += 1
        break
      }
      None => break
      _ => { self.pos += 1 }
    }
  }
}

