///
/// Returns `Json::Object(...)` with keys sorted alphabetically for
/// determinism. Raises `TomlError` on invalid input.
pub fn parse_toml(text : String) -> Json raise TomlError {
  let parser = TomlParser::new(text)
  // Flat entries preserving insertion order.
  let mut entries : Array[(Array[String], TomlVal)] = []
  let mut seen : Map[String, Unit] = Map::default()
  let mut table_path : Array[String] = []

  loop {
    parser.skip_ws_nl()
    match parser.peek() {
      None => break
      Some(0x23) => { // '#'
        parser.skip_comment()
