// Skip the rest of the current line (after value or table header).
fn skip_rest_of_line(self : TomlParser) -> Unit {
  loop {
    match self.peek() {
      None => break
      Some(0x0A) | Some(0x0D) => break // newline
      Some(0x23) => { // '#'
        self.skip_comment()
        break
      }
      _ => { self.pos += 1 }
    }
  }
}

// Parse a table path like "owner" or "database.settings"
fn parse_table_path(self : TomlParser) -> Array[String] raise TomlError {
  let mut path : Array[String] = []
  loop {
    self.skip_ws()
    let key = parse_bare_key(self)
    path.push(key)
    self.skip_ws()
    match self.peek() {
      Some(0x2E) => { self.pos += 1 } // '.'
      _ => break
    }
  }
  path
}

// Parse one or more bare keys separated by dots.
fn parse_keys(self : TomlParser) -> Array[String] raise TomlError {
  let mut keys : Array[String] = []
  loop {
    let key = parse_bare_key(self)
    keys.push(key)
    self.skip_ws()
    match self.peek() {
      Some(0x2E) => { self.pos += 1 } // '.'
      _ => break
    }
  }
  keys
}

// Parse a single bare key (alphanumeric, underscore, dash).
fn parse_bare_key(self : TomlParser) -> String raise TomlError {
  let mut chars : Array[Char] = []
  let start_line = self.line
  loop {
    match self.peek() {
      Some(c) if is_key_char(c) => {
        let ch = self.text[self.pos].to_char().or(
          fail("invalid UTF-16 at position \(self.pos)"),
