        chars.push(ch)
        self.pos += 1
      }
      _ => break
    }
  }
  if chars.is_empty() {
    raise InvalidSyntax("expected a key at line \(start_line)")
  }
  // Build string from chars
  let mut s = StringBuilder::new()
  for ch in chars { s.write_char(ch) }
  s.to_string()
}

fn is_key_char(code : Int) -> Bool {
  (code >= 0x41 && code <= 0x5A) || // A-Z
  (code >= 0x61 && code <= 0x7A) || // a-z
  (code >= 0x30 && code <= 0x39) || // 0-9
