  match self.peek() {
    Some(0x2D) | Some(0x2B) => {
      let ch = self.text[self.pos].to_char().or(fail(""))
      s.write_char(ch)
      self.pos += 1
    }
    _ => ()
  }
  // Digits and underscores
  loop {
    match self.peek() {
      Some(c) if c >= 0x30 && c <= 0x39 => {
        let ch = self.text[self.pos].to_char().or(fail(""))
        s.write_char(ch)
        self.pos += 1
      }
      Some(0x5F) => { self.pos += 1 } // Skip '_' separators
      _ => break
    }
  }
  let text = s.to_string()
  if text.is_empty() {
    raise InvalidSyntax("expected integer at line \(self.line)")
  }
