        chars.push(ch)
        self.pos += 1
      }
      _ => break
    }
  }
  let mut s = StringBuilder::new()
  for ch in chars { s.write_char(ch) }
  let text = s.to_string()
  match text {
    "true" => TomlBool(true)
    "false" => TomlBool(false)
    _ => {
      self.pos = start_pos
      raise InvalidValue("invalid value '\(text)' at line \(self.line)")
    }
  }
}

// Parse an array of values: [val1, val2, ...]
fn parse_array(self : TomlParser) -> Array[TomlVal] raise TomlError {
  // Current character is the opening '['
  self.pos += 1
  let mut items : Array[TomlVal] = []
  loop {
    self.skip_ws_nl()
    match self.peek() {
      None => raise InvalidSyntax("unterminated array at line \(self.line)")
      Some(0x5D) => { // ']'
        self.pos += 1
        break
      }
      Some(0x23) => { // '#'
        self.skip_comment()
      }
      Some(0x2C) => { // ','
        self.pos += 1
      }
      _ => {
        let val = parse_value(self)
        items.push(val)
      }
    }
