// Build nested Json from flat key-path entries.
fn build_json(entries : Array[(Array[String], TomlVal)]) -> Json {
  let mut result : Map[String, Json] = Map::default()
  for (path, val) in entries {
    insert_into_map(result, path, 0, val)
  }
  // Sort top-level keys for determinism, recursing into nested objects.
  sort_map_keys(result)
}

fn insert_into_map(
  map : Map[String, Json],
  path : Array[String],
  depth : Int,
  val : TomlVal
