  let key = path[depth]
  if depth == path.length() - 1 {
    map[key] = toml_val_to_json(val)
  } else if map.contains(key) {
    let existing = map[key]
    match existing {
      Json::Object(submap) => {
        insert_into_map(submap, path, depth + 1, val)
        map[key] = Json::object(submap)
      }
      _ => {
        let submap : Map[String, Json] = Map::default()
        insert_into_map(submap, path, depth + 1, val)
        map[key] = Json::object(submap)
      }
    }
  } else {
    let submap : Map[String, Json] = Map::default()
    insert_into_map(submap, path, depth + 1, val)
    map[key] = Json::object(submap)
  }
