{"content": "// TOML to JSON CLI tool.
// Reads TOML from a file or stdin and outputs JSON to stdout.

async fn main {
  let matches = @argparse.parse(
    Command(
      "tomljson",
      about="Convert TOML to JSON.",
      flags=[
        FlagArg("stdin", long="stdin", about="Read TOML from stdin."),
      ],
      positionals=[
        PositionArg(
          "input",
          default_values=["-"],
          about="TOML file path (or use --stdin).",
        ),
      ],
    ),
  )

  let use_stdin = match matches.flags.get("stdin") {
    Some(v) => v
    None => false
  }
  let input_path = match matches.values.get("input") {
    Some(arr) if arr.length() > 0 => arr[0]
    _ => "-"
  }

  let text = if use_stdin || input_path == "-" {
    @stdio.stdin.read_all().text()
  } else {
    @fs.read_file(input_path).text()
  }

  let json = @src.parse_toml(text) catch {
    e => {
      @stdio.stderr.write_string("\{e}\n")
      return
    }
  }
  @stdio.stdout.write_string(json.stringify())
  @stdio.stdout.write_string("\n")
}
