  let mut use_stdin = false
  let mut file_path : String? = None
  let mut i = 1 // skip program name
  while i < args.length() {
    let arg = args[i]
    if arg == "--stdin" {
      use_stdin = true
    } else if arg.starts_with("-") && arg != "-" {
      // Unknown flag, skip
    } else {
      file_path = Some(arg)
    }
    i += 1
  }

  let text = if use_stdin || file_path == None || file_path.as_some() == "-" {
    // Read from stdin
    @fs.read_file_to_string("/dev/stdin") catch {
      _ => {
        eprintln("error: cannot read stdin")
        return
      }
    }
  } else {
    let path = file_path.as_some()
    @fs.read_file_to_string(path) catch {
      _ => {
        eprintln("error: cannot read file '\{path}'")
        return
      }
    }
  }

  let json = @src.parse_toml(text) catch {
    e => {
      eprintln("\{e}")
      return
    }
  }
  println(json.stringify())
}
